CREATE TABLE "team" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(200) NOT NULL,
    "team_type" varchar(30) NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE "team_member" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "team_id" bigint NOT NULL,
    "user_id" bigint NOT NULL,
    "joined_at" date,
    "left_at" date,
    CONSTRAINT "team_member_team_id_fkey"
        FOREIGN KEY ("team_id") REFERENCES "team" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "team_member_user_id_fkey"
        FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "team_coach" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "team_id" bigint NOT NULL,
    "coach_user_id" bigint NOT NULL,
    CONSTRAINT "team_coach_team_id_fkey"
        FOREIGN KEY ("team_id") REFERENCES "team" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "team_coach_coach_user_id_fkey"
        FOREIGN KEY ("coach_user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

COMMENT ON COLUMN "team"."team_type" IS 'competition либо regional_squad: уточнить при проработке командных зачётов';
